            reject: [{ re: "it's|it’s|its'", hint: 'The possessive of "it" has no apostrophe.' }, { re: '^their', hint: 'This word points back to more than one thing.' }, { re: '^(her|his)', hint: 'A language is not a person. Which possessive goes with a thing?' }],
